  -- FP00631 find_FP00631  
  SET @v_dSql = ''

  SET @v_dSql += ' IF OBJECT_ID(''tempdb..#SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP'') IS NOT NULL DROP TABLE #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP;'+char(10)

  SET @v_dSql += '                          SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.ITEM_ID, A.FLOW_ID,A.ITEM_CLASS,A.PACK_PRODUCT_GROUP_CODE'+char(10)
  SET @v_dSql += '                                ,(CASE WHEN LEFT(A.FLOW_ID,5) = ''A9000'' AND ISNULL(C.LEVEL_4_NAME, ''-'') = ''-'' THEN C.LEVEL_3_NAME'+char(10)
  SET @v_dSql += '                                       WHEN LEFT(A.FLOW_ID,5) = ''A9000'' THEN ISNULL(C.LEVEL_4_NAME, ''-'')'+char(10)
  SET @v_dSql += '                                       ELSE C.LEVEL_3_NAME END) AS ITEM_TYPE'+char(10)
  SET @v_dSql += '                                ,ISNULL(A.NICK_NAME,''-'') AS NICK_NAME, ISNULL(A.PACK_PRODUCT_GROUP_CODE,''-'') AS PJT_GROUP_NAME, C.* '+char(10)
  SET @v_dSql += '   INTO  #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP FROM SCM_ITEM_M A WITH(NOLOCK) INNER JOIN SCM_ITEM_CLASS_M C WITH(NOLOCK)'+char(10)
  SET @v_dSql += '                          ON	 A.ITEM_CLASS  = C.CLASS_ID'+char(10)
  SET @v_dSql += '                          WHERE    A.ACTIVE_FLAG = ''Y'''+char(10)
  SET @v_dSql += '                          AND    C.USE_FLAG = ''Y'''+char(10)

  SET @v_dSql += '      IF  OBJECT_ID(''tempdb..#SCM_SYS_LOOKUP_VALUE_TEMP'') IS NOT NULL    '+char(10)
  SET @v_dSql += '        DROP TABLE #SCM_SYS_LOOKUP_VALUE_TEMP;                         '+char(10)
  SET @v_dSql += 'SELECT                                                                      '+char(10)
  SET @v_dSql += '			B.LOOKUP_TYPE_CODE            ,                                 '+char(10)
  SET @v_dSql += '			B.SEGMENT1   AS SIMULATION_NAME ,                               '+char(10)
  SET @v_dSql += '			B.SEGMENT2   AS SITE_ID         ,                               '+char(10)
  SET @v_dSql += '			B.SEGMENT3   AS DIVISION_ID     ,                               '+char(10)
  SET @v_dSql += '			B.SEGMENT4   AS PLANT_ID        ,                               '+char(10)
  SET @v_dSql += '			B.SEGMENT5   AS STOCK_POINT     ,                               '+char(10)
  SET @v_dSql += '			B.ATTRIBUTE1 AS STOCK_TYPE      ,                               '+char(10)
  SET @v_dSql += '			B.ATTRIBUTE2 AS ASSY_BOH        ,								'+char(10)
  SET @v_dSql += '			B.ATTRIBUTE3 AS CELL_BOH        ,                               '+char(10)
  SET @v_dSql += '			B.ATTRIBUTE4 AS PACK_BOH                                        '+char(10)
  SET @v_dSql += '			INTO #SCM_SYS_LOOKUP_VALUE_TEMP                                 '+char(10)
  SET @v_dSql += '			FROM                                                            '+char(10)
  SET @v_dSql += '			SCM_SYS_LOOKUP_VALUE B WITH(NOLOCK)                             '+char(10)
  SET @v_dSql += '			WHERE                                                           '+char(10)
  SET @v_dSql += '			B.ACTIVE_FLAG      = ''Y''                                        '+char(10)
  SET @v_dSql += '			AND     B.LOOKUP_TYPE_CODE = ''SIMULATION_BOH''                   '+char(10)
  SET @v_dSql += '			AND     B.SEGMENT1         = ''CELL_SIMULATION''                  '+char(10)
  SET @v_dSql += '                                                                            '+char(10)


  SET @v_dSql += '      IF  OBJECT_ID(''tempdb..#SCM_SYS_LOOKUP_TYPE_VALUE_TEMP'') IS NOT NULL    '+char(10)
  SET @v_dSql += '        DROP TABLE #SCM_SYS_LOOKUP_TYPE_VALUE_TEMP;                         '+char(10)
  SET @v_dSql += 'SELECT                                                                      '+char(10)
  SET @v_dSql += '					B.LOOKUP_TYPE_CODE            ,                         '+char(10)
  SET @v_dSql += '					B.SEGMENT1   AS SIMULATION_NAME ,                       '+char(10)
  SET @v_dSql += '					B.SEGMENT2   AS SITE_ID         ,                       '+char(10)
  SET @v_dSql += '					B.SEGMENT3   AS DIVISION_ID     ,                       '+char(10)
  SET @v_dSql += '					B.SEGMENT4   AS PLANT_ID        ,                       '+char(10)
  SET @v_dSql += '					B.SEGMENT5   AS STOCK_POINT     ,                       '+char(10)
  SET @v_dSql += '					B.ATTRIBUTE1 AS STOCK_TYPE      ,                       '+char(10)
  SET @v_dSql += '					B.ATTRIBUTE2 AS ASSY_BOH        ,                       '+char(10)
  SET @v_dSql += '					B.ATTRIBUTE3 AS CELL_BOH        ,                       '+char(10)
  SET @v_dSql += '					B.ATTRIBUTE4 AS PACK_BOH                                '+char(10)
  SET @v_dSql += '			INTO #SCM_SYS_LOOKUP_TYPE_VALUE_TEMP                            '+char(10)
  SET @v_dSql += '			FROM                                                            '+char(10)
  SET @v_dSql += '					SCM_SYS_LOOKUP_TYPE_M A WITH(NOLOCK),                   '+char(10)
  SET @v_dSql += '					SCM_SYS_LOOKUP_VALUE B WITH(NOLOCK)                     '+char(10)
  SET @v_dSql += '			WHERE                                                           '+char(10)
  SET @v_dSql += '					A.ACTIVE_FLAG      = ''Y''                                '+char(10)
  SET @v_dSql += '			AND     B.ACTIVE_FLAG      = ''Y''                                '+char(10)
  SET @v_dSql += '			AND     A.LOOKUP_TYPE_CODE = B.LOOKUP_TYPE_CODE                 '+char(10)
  SET @v_dSql += '			AND     A.LOOKUP_TYPE_CODE = ''SIMULATION_BOH''                   '+char(10)
  SET @v_dSql += '			AND     B.SEGMENT1         = ''CELL_SIMULATION''                  '+char(10)


  SET @v_dSql += ' IF OBJECT_ID(''tempdb..#TblFP00631_TEMP'') IS NOT NULL DROP TABLE #TblFP00631_TEMP;'+char(10)
