  SET @v_dSql += '      WITH BOM_INFO AS ('+char(10)
  --SET @v_dSql += '      	-- BOM 전개 코드 :  1순위 --'+char(10)
  SET @v_dSql += '        SELECT  A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID'+char(10)
  SET @v_dSql += '      			, A.PARENT_ITEM_ID, A.PARENT_UOM'+char(10)
  SET @v_dSql += '      			, A.CHILD_ITEM_ID AS P5000_ITEM_ID, A.CHILD_UOM'+char(10)
