  SET @v_dSql += '    					INNER HASH JOIN ( '+char(10)
  SET @v_dSql += '    							SELECT S.COMPANY_ID , S.DIVISION_ID, S.SITE_ID , S.ITEM_ID , S.ITEM_CLASS , RIGHT(S.FLOW_ID,5) AS FLOW_ID , S.CLASS_NAME , S.LEVEL'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_1_CODE , S.LEVEL_1_NAME , S.LEVEL_1_ID'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_2_CODE , S.LEVEL_2_NAME , S.LEVEL_2_ID'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_3_CODE , S.LEVEL_3_NAME , S.LEVEL_3_ID'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_4_CODE , S.LEVEL_4_NAME , S.LEVEL_4_ID'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_5_CODE , S.LEVEL_5_NAME , S.LEVEL_5_ID'+char(10)
  --SET @v_dSql += '    							FROM   SCM_ITEM_M I WITH(NOLOCK), SCM_ITEM_CLASS_M S WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    							FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP S '+char(10)
  --SET @v_dSql += '    							WHERE  I.ITEM_CLASS   = S.CLASS_ID'+char(10)
  --SET @v_dSql += '    							AND    I.ACTIVE_FLAG  = ''Y'''+char(10)
  --SET @v_dSql += '    							AND    S.USE_FLAG     = ''Y'''+char(10)
  SET @v_dSql += '    							WHERE  1   = 1 '+char(10)
  SET @v_dSql += '    							AND    S.LEVEL_3_NAME IN ( ''Pack'', ''Module'' )'+char(10)
  SET @v_dSql += '    							AND    RIGHT(S.FLOW_ID,5) IN ( ''P9500'',''P5500'' )'+char(10)
  SET @v_dSql += '    					) IM'+char(10)
  SET @v_dSql += '    					ON   1=1'+char(10)
  SET @v_dSql += '    					AND  IM.ITEM_ID          = A.FP_APPLY_ITEM_ID'+char(10)
  SET @v_dSql += '    					AND  IM.COMPANY_ID       = A.COMPANY_ID'+char(10)
  SET @v_dSql += '    					AND  IM.DIVISION_ID      = A.DIVISION_ID'+char(10)
  SET @v_dSql += '    					AND  IM.SITE_ID          = A.SITE_ID'+char(10)
  --SET @v_dSql += '    					INNER HASH JOIN ( --<V: LOOKUP에 STOCK POINT 참조 >--'+char(10)
  SET @v_dSql += '    					INNER HASH JOIN #SCM_SYS_LOOKUP_VALUE_TEMP V '+char(10)
  --SET @v_dSql += '    							SELECT B.LOOKUP_TYPE_CODE'+char(10)
  --SET @v_dSql += '    								   , B.SEGMENT1 AS SIMULATION_NAME , B.SEGMENT2 AS SITE_ID , B.SEGMENT3 AS DIVISION_ID , B.SEGMENT4 AS PLANT_ID , B.SEGMENT5 AS STOCK_POINT'+char(10)
  --SET @v_dSql += '    				 				   , B.ATTRIBUTE1 AS STOCK_TYPE , B.ATTRIBUTE2 AS ASSY_BOH , B.ATTRIBUTE3 AS CELL_BOH, B.ATTRIBUTE4 AS PACK_BOH'+char(10)
  --SET @v_dSql += '    							FROM   SCM_SYS_LOOKUP_VALUE  B WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '    							WHERE  B.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '    							AND    B.LOOKUP_TYPE_CODE = ''SIMULATION_BOH'''+char(10)
  --SET @v_dSql += '    							AND    B.SEGMENT1         = ''CELL_SIMULATION'''+char(10)
  --SET @v_dSql += '    					) V'+char(10)
  SET @v_dSql += '    					ON   A.SITE_ID               = V.SITE_ID'+char(10)
  SET @v_dSql += '    					AND  A.DIVISION_ID           = V.DIVISION_ID'+char(10)
  SET @v_dSql += '    					AND  A.PLANT_ID              = V.PLANT_ID'+char(10)
  SET @v_dSql += '    					AND  A.STOCK_TYPE            = V.STOCK_TYPE'+char(10)
  SET @v_dSql += '    					AND  A.STORAGE_ID            = V.STOCK_POINT'+char(10)
  --SET @v_dSql += '    					AND  V.PACK_BOH              = ''Y''     --->  BOH 타입에 따라서 조건 변경해줘야 함.'+char(10)
  SET @v_dSql += '    					AND  V.PACK_BOH              = ''Y''     '+char(10)
  SET @v_dSql += '    					WHERE  CUTOFF_DATE ='+char(10)
  SET @v_dSql += '' + @v_plan_date+''+char(10)
  --SET @v_dSql += '  ---> instance date'+char(10)
  SET @v_dSql += '    					AND EXISTS ('+char(10)
  SET @v_dSql += '    						SELECT 1'+char(10)
  SET @v_dSql += '    						FROM   FP_INSTANCE_INFO_V VV WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    						WHERE  VV.INSTANCE_ID ='+char(10)
  SET @v_dSql += '' + @v_pack_instance_id+''+char(10)
  SET @v_dSql += '    						AND    A.COMPANY_ID   = VV.COMPANY_ID'+char(10)
  SET @v_dSql += '    						AND    A.DIVISION_ID  = VV.DIVISION_ID'+char(10)
  SET @v_dSql += '    						AND    A.SITE_ID      = VV.SITE_ID'+char(10)
  SET @v_dSql += '    					)'+char(10)
  --SET @v_dSql += '    					AND  A.STOCK_TYPE = ''INVENTORY''  ---  ERP 재고'+char(10)
  SET @v_dSql += '    					AND  A.STOCK_TYPE = ''INVENTORY''  '+char(10)
  SET @v_dSql += '    					AND  A.QTY2 > 0'+char(10)
  SET @v_dSql += '    					UNION ALL'+char(10)
  --SET @v_dSql += '    					/* PACK MES BOH 조회 */'+char(10)
  SET @v_dSql += '    					SELECT A.CUTOFF_DATE , A.COMPANY_ID , A.DIVISION_ID , A.SITE_ID , A.PLANT_ID , A.STORAGE_ID, A.FP_APPLY_OPERATION_ID AS OPERATION_ID'+char(10)
  SET @v_dSql += '    							 , A.STOCK_TYPE, A.FP_APPLY_WIPQTY AS QTY'+char(10)
  SET @v_dSql += '    							 , ISNULL(WIPHOLD_YN,''N'') AS WIPHOLD_YN'+char(10)
  SET @v_dSql += '    							 , CASE WHEN CONVERT(VARCHAR,A.AVAILABLE_DATE,112) <= CONVERT(VARCHAR,A.CUTOFF_DATE,112) AND  ISNULL(WIPHOLD_YN,''N'') <> ''Y'' THEN A.FP_APPLY_WIPQTY ELSE NULL END AS GOOD_QTY'+char(10)
  SET @v_dSql += '    							 , CASE WHEN ISNULL(WIPHOLD_YN,''N'') = ''Y'' THEN A.FP_APPLY_WIPQTY ELSE NULL END AS HOLD_QTY'+char(10)
  SET @v_dSql += '    							 , A.FP_APPLY_ITEM_ID AS ITEM_ID'+char(10)
  SET @v_dSql += '    							 , IM.FLOW_ID , IM.LEVEL_1_CODE, IM.LEVEL_2_CODE, IM.LEVEL_2_NAME, IM.LEVEL_3_CODE, IM.LEVEL_3_NAME'+char(10)
  SET @v_dSql += '    					FROM   SCM_STOCK_H_V A WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '    					INNER HASH JOIN ( --<IM: ITEM CODE 검색용 >--'+char(10)
  SET @v_dSql += '    					INNER HASH JOIN ( '+char(10)
  SET @v_dSql += '    							SELECT S.COMPANY_ID , S.DIVISION_ID, S.SITE_ID , S.ITEM_ID , S.ITEM_CLASS , RIGHT(S.FLOW_ID,5) AS FLOW_ID , S.CLASS_NAME , S.LEVEL'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_1_CODE , S.LEVEL_1_NAME , S.LEVEL_1_ID'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_2_CODE , S.LEVEL_2_NAME , S.LEVEL_2_ID'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_3_CODE , S.LEVEL_3_NAME , S.LEVEL_3_ID'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_4_CODE , S.LEVEL_4_NAME , S.LEVEL_4_ID'+char(10)
  SET @v_dSql += '    									 , S.LEVEL_5_CODE , S.LEVEL_5_NAME , S.LEVEL_5_ID'+char(10)
  --SET @v_dSql += '    							FROM   SCM_ITEM_M I WITH(NOLOCK), SCM_ITEM_CLASS_M S WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    							FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP S '+char(10)
  --SET @v_dSql += '    							WHERE  I.ITEM_CLASS   = S.CLASS_ID'+char(10)
  SET @v_dSql += '    							WHERE  1   = 1'+char(10)
  --SET @v_dSql += '    							AND    I.ACTIVE_FLAG  = ''Y'''+char(10)
  --SET @v_dSql += '    							AND    S.USE_FLAG     = ''Y'''+char(10)
  SET @v_dSql += '    							AND    S.LEVEL_3_NAME IN ( ''Pack'', ''Module'' )'+char(10)
  SET @v_dSql += '    							AND    RIGHT(S.FLOW_ID,5) IN ( ''P9500'',''P5500'' )'+char(10)
  SET @v_dSql += '    					) IM'+char(10)
  SET @v_dSql += '    					ON   1=1'+char(10)
  SET @v_dSql += '    					AND  IM.ITEM_ID     = A.FP_APPLY_ITEM_ID'+char(10)
  SET @v_dSql += '    					AND  IM.COMPANY_ID  = A.COMPANY_ID'+char(10)
  SET @v_dSql += '    					AND  IM.DIVISION_ID = A.DIVISION_ID'+char(10)
  SET @v_dSql += '    					AND  IM.SITE_ID     = A.SITE_ID'+char(10)
  --SET @v_dSql += '    					INNER HASH JOIN ( --<V: LOOKUP에 STOCK POINT 참조 >--'+char(10)
  SET @v_dSql += '    					INNER HASH JOIN #SCM_SYS_LOOKUP_VALUE_TEMP V '+char(10)
  --SET @v_dSql += '    							SELECT B.LOOKUP_TYPE_CODE'+char(10)
  --SET @v_dSql += '    								   , B.SEGMENT1 AS SIMULATION_NAME , B.SEGMENT2 AS SITE_ID , B.SEGMENT3 AS DIVISION_ID , B.SEGMENT4 AS PLANT_ID , B.SEGMENT5 AS STOCK_POINT'+char(10)
  --SET @v_dSql += '    								   , B.ATTRIBUTE1 AS STOCK_TYPE , B.ATTRIBUTE2 AS ASSY_BOH , B.ATTRIBUTE3 AS CELL_BOH, B.ATTRIBUTE4 AS PACK_BOH'+char(10)
  --SET @v_dSql += '    							FROM   SCM_SYS_LOOKUP_VALUE B WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '    							WHERE  B.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '    							AND    B.LOOKUP_TYPE_CODE = ''SIMULATION_BOH'''+char(10)
  --SET @v_dSql += '    							AND    B.SEGMENT1         = ''CELL_SIMULATION'''+char(10)
  --SET @v_dSql += '    					) V'+char(10)
  SET @v_dSql += '    					ON   A.SITE_ID               = V.SITE_ID'+char(10)
  SET @v_dSql += '    					AND  A.DIVISION_ID           = V.DIVISION_ID'+char(10)
  SET @v_dSql += '    					AND  A.PLANT_ID              = V.PLANT_ID'+char(10)
  SET @v_dSql += '    					AND  A.STOCK_TYPE            = V.STOCK_TYPE'+char(10)
  SET @v_dSql += '    					AND  A.FP_APPLY_OPERATION_ID = V.STOCK_POINT'+char(10)
  --SET @v_dSql += '    					AND  V.PACK_BOH              = ''Y''   --->  BOH 타입에 따라서 조건 변경해줘야 함.'+char(10)
  SET @v_dSql += '    					AND  V.PACK_BOH              = ''Y''   '+char(10)
  SET @v_dSql += '    					WHERE  A.CUTOFF_DATE ='+char(10)
  SET @v_dSql += '' + @v_plan_date+''+char(10)
  --SET @v_dSql += '     --- INSTANCE_DATE'+char(10)
  SET @v_dSql += '    					AND  A.STORAGE_ID    =  ''MES'''+char(10)
  --SET @v_dSql += '    					AND  A.STOCK_TYPE    =  ''WIP''     --- MES 재고'+char(10)
  SET @v_dSql += '    					AND  A.STOCK_TYPE    =  ''WIP''    '+char(10)
  SET @v_dSql += '    					AND EXISTS ('+char(10)
  SET @v_dSql += '    						SELECT 1'+char(10)
  SET @v_dSql += '    						FROM   FP_INSTANCE_INFO_V VV WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    						WHERE  VV.INSTANCE_ID ='+char(10)
  SET @v_dSql += '' + @v_pack_instance_id+''+char(10)
  SET @v_dSql += '    						AND    A.COMPANY_ID   = VV.COMPANY_ID'+char(10)
  SET @v_dSql += '    						AND    A.DIVISION_ID  = VV.DIVISION_ID'+char(10)
  SET @v_dSql += '    						AND    A.SITE_ID      = VV.SITE_ID'+char(10)
  SET @v_dSql += '    					)'+char(10)
  SET @v_dSql += '    					AND  A.FP_APPLY_WIPQTY > 0'+char(10)
  SET @v_dSql += '    			) A'+char(10)
  SET @v_dSql += '    			WHERE 1=1'+char(10)
  SET @v_dSql += '    			GROUP BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.OPERATION_ID, ITEM_ID'+char(10)
  SET @v_dSql += '      	) C'+char(10)
  SET @v_dSql += '      	ON  A.COMPANY_ID   = C.COMPANY_ID'+char(10)
  SET @v_dSql += '      	AND A.DIVISION_ID  = C.DIVISION_ID'+char(10)
  SET @v_dSql += '      	AND A.SITE_ID      = C.SITE_ID'+char(10)
  SET @v_dSql += '      	AND A.PLANT_ID     = C.PLANT_ID'+char(10)
  SET @v_dSql += '      	AND A.OPERATION_ID = C.OPERATION_ID'+char(10)
  SET @v_dSql += '      	AND A.ITEM_ID      = C.ITEM_ID'+char(10)
  SET @v_dSql += '      	GROUP BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.OPERATION_ID, A.PRODUCTION_TYPE, A.MARKET, A.LINE_ID, A.ITEM_ID, A.PACK_GROUP_CODE, A.NICK_NAME, C.BOH_QTY, A.ITEM_TYPE'+char(10)
  SET @v_dSql += '      		   , B.CATEGORY_ID, B.CATEGORY_NAME, B.CATEGORY_ORDER, B.PSI_ORDER, B.SHOP_TYPE, B.SHOP_ORDER'+char(10)
  SET @v_dSql += '      )'+char(10)
  --SET @v_dSql += '      -- pack scp target : release'+char(10)
  SET @v_dSql += '      , PACK_SCP_TARGET_REL AS ('+char(10)
  SET @v_dSql += '        SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID'+char(10)
  SET @v_dSql += '          	 , A.ITEM_ID, A.ITEM_ID AS PACK_GROUP_CODE'+char(10)
  SET @v_dSql += '          	 , CONVERT(VARCHAR, ISNULL(A.MFG_DATE, E.YYYYMMDD), 112) AS PLAN_DATE'+char(10)
  SET @v_dSql += '          	 , SUM(A.MFG_QTY) AS SCP_QTY'+char(10)
  SET @v_dSql += '          	 , A.PRODUCTION_TYPE, A.MARKET'+char(10)
  SET @v_dSql += '        FROM   FP_WEEKLY_DEMAND_PRODUCT_H A WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '        INNER HASH JOIN ( -- B: INSTANCE, PLAN_ID INFO'+char(10)
  SET @v_dSql += '        INNER HASH JOIN ( '+char(10)
  --SET @v_dSql += '          		-- RELEASE PLAN : LASTEST PLAN'+char(10)
  SET @v_dSql += '          		SELECT B.SCP_PLAN_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, B.PST, B.PLAN_WEEK'+char(10)
  SET @v_dSql += '          		FROM ('+char(10)
  SET @v_dSql += '            			SELECT DISTINCT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID'+char(10)
  SET @v_dSql += '            			FROM   FP_INSTANCE_INFO_V A WITH(NOLOCK)'+char(10)
  SET @v_dSql += '            			WHERE  INSTANCE_ID ='+char(10)
  SET @v_dSql += '' + @v_pack_instance_id+''+char(10)
  SET @v_dSql += '          		) A'+char(10)
  SET @v_dSql += '          		, ('+char(10)
  SET @v_dSql += '            			SELECT MAX(A.SCP_PLAN_ID) AS SCP_PLAN_ID, A.DIVISION_ID, A.SHOP_GROUP_ID, CONVERT(DATE, SUBSTRING(MAX(A.SCP_PLAN_ID),1,8)) AS PST'+char(10)
  SET @v_dSql += '            				, ( SELECT TOP 1 AA.ISO_YYYYWW FROM TH_UIS_CAL AA WITH(NOLOCK)'+char(10)
  SET @v_dSql += '            					WHERE  AA.YYYYMMDD = SUBSTRING(MAX(A.SCP_PLAN_ID),1,8)) AS PLAN_WEEK'+char(10)
  SET @v_dSql += '            			FROM   FP_WEEKLY_DEMAND_PRODUCT_H A WITH(NOLOCK), ('+char(10)
  SET @v_dSql += '            				SELECT DISTINCT DIVISION_ID + A.INSTANCE_TYPE AS TARGET_INFO'+char(10)
  SET @v_dSql += '            				FROM   FP_INSTANCE_INFO_V A WITH(NOLOCK)'+char(10)
  SET @v_dSql += '            				WHERE  INSTANCE_ID ='+char(10)
  SET @v_dSql += '' + @v_pack_instance_id+''+char(10)
  SET @v_dSql += '            			) B'+char(10)
  SET @v_dSql += '            			WHERE A.DIVISION_ID+A.SHOP_GROUP_ID = B.TARGET_INFO'+char(10)
  SET @v_dSql += '            			GROUP BY A.DIVISION_ID, A.SHOP_GROUP_ID'+char(10)
  SET @v_dSql += '          		) B'+char(10)
  SET @v_dSql += '          		WHERE A.DIVISION_ID = B.DIVISION_ID'+char(10)
  SET @v_dSql += '          		AND'+char(10)
  SET @v_dSql += '' + @v_is_rel_pack+''+char(10)
  --SET @v_dSql += ' = ''Y'' -- pack rel check'+char(10)
  SET @v_dSql += ' = ''Y'' '+char(10)
  SET @v_dSql += '        ) B'+char(10)
  SET @v_dSql += '        ON   1=1'+char(10)
  SET @v_dSql += '        AND  A.SCP_PLAN_ID =  B.SCP_PLAN_ID'+char(10)
  SET @v_dSql += '        AND  A.COMPANY_ID  =  B.COMPANY_ID'+char(10)
  SET @v_dSql += '        AND  A.SITE_ID     =  B.SITE_ID'+char(10)
  SET @v_dSql += '        AND  A.DIVISION_ID =  B.DIVISION_ID'+char(10)
  SET @v_dSql += '        AND  A.PLANT_ID    =  B.PLANT_ID'+char(10)
  SET @v_dSql += '        LEFT OUTER HASH JOIN TH_UIS_CAL E WITH(NOLOCK)'+char(10)
  SET @v_dSql += '        ON  E.ISO_YYYYWW = A.MFG_WEEK'+char(10)
  --SET @v_dSql += '        AND E.DAY_SEQ = ''1'' -- 각 주의 일요일'+char(10)
  SET @v_dSql += '        AND E.DAY_SEQ = ''1'' '+char(10)
  SET @v_dSql += '        INNER JOIN ('+char(10)
  SET @v_dSql += '            	SELECT C.* '+char(10)
  --SET @v_dSql += '            	SELECT B.ITEM_ID, B.SITE_ID, C.*'+char(10)
  --SET @v_dSql += '            	FROM   SCM_ITEM_M B WITH(NOLOCK), SCM_ITEM_CLASS_M C WITH(NOLOCK)'+char(10)
  SET @v_dSql += '            	FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP C '+char(10)
  SET @v_dSql += '            	WHERE  1   = 1 '+char(10)
  --SET @v_dSql += '            	WHERE  B.ITEM_CLASS   = C.CLASS_ID'+char(10)
  --SET @v_dSql += '            	AND    C.LEVEL_3_CODE IN ( ''AP'', ''AM'' )  -- PACK ONLY'+char(10)
  SET @v_dSql += '             	AND    C.LEVEL_3_CODE IN ( ''AP'', ''AM'' )  '+char(10)
  --SET @v_dSql += '            	AND    B.ACTIVE_FLAG  = ''Y'''+char(10)
  --SET @v_dSql += '            	AND    C.USE_FLAG     = ''Y'''+char(10)
  SET @v_dSql += '        ) M'+char(10)
  SET @v_dSql += '        ON   1=1'+char(10)
  SET @v_dSql += '        AND  A.ITEM_ID = M.ITEM_ID'+char(10)
  SET @v_dSql += '        AND  A.SITE_ID = M.SITE_ID'+char(10)
  SET @v_dSql += '        WHERE 1=1'+char(10)
  SET @v_dSql += '        GROUP BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.ITEM_ID, ISNULL(A.MFG_DATE, E.YYYYMMDD), A.PRODUCTION_TYPE, A.MARKET'+char(10)
  SET @v_dSql += '      )'+char(10)
  SET @v_dSql += '      , PACK_SCP_TARGET AS ('+char(10)
  --SET @v_dSql += '    			  -- SCP Target : draft plan'+char(10)
  SET @v_dSql += '    			  SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID'+char(10)
  SET @v_dSql += '      				   , A.ITEM_ID, A.ITEM_ID AS PACK_GROUP_CODE'+char(10)
  SET @v_dSql += '      				   , CONVERT(VARCHAR, A.PLAN_DATE, 112) AS PLAN_DATE'+char(10)
  SET @v_dSql += '      				   , SUM(A.SALES_QTY) AS SCP_QTY'+char(10)
  SET @v_dSql += '      				   , A.PRODUCTION_TYPE, A.MARKET'+char(10)
  SET @v_dSql += '    			  FROM   '+@PACK_AMEND_SALES_TABLE+' A WITH(NOLOCK)'+char(10)
  SET @v_dSql += '      			WHERE  1=1'+char(10)
  SET @v_dSql += '      			AND'+char(10)
  SET @v_dSql += '' + @v_is_rel_pack+''+char(10)
  --SET @v_dSql += ' != ''Y'' -- draft plan'+char(10)
  SET @v_dSql += ' != ''Y'' '+char(10)
  SET @v_dSql += '      			AND    A.INSTANCE_ID  ='+char(10)
  SET @v_dSql += '' + @v_pack_instance_id+''+char(10)
  --SET @v_dSql += '              ---> UI FILTER'+char(10)
  --SET @v_dSql += '      			AND    A.FP_PLAN_ID IN ( '+@PACK_PLAN_LT+' )  ---> UI FILTER'+char(10)
  SET @v_dSql += '      			AND    A.FP_PLAN_ID IN ( '+@PACK_PLAN_LT+' )  '+char(10)
  SET @v_dSql += '      			AND    A.PLAN_DATE BETWEEN CONVERT(DATETIME,'+char(10)
  SET @v_dSql += '' + @v_plan_date+''+char(10)
  SET @v_dSql += ') AND CONVERT(DATETIME,'+char(10)
  SET @v_dSql += '' + @v_bucket_to+''+char(10)
