  SET @v_dSql += '          			AND   A.SCP_PLAN_ID = C.MAX_SCP_PLAN_ID'+char(10)
  SET @v_dSql += '          			AND   A.SHOP_GROUP_ID = C.SHOP_GROUP_ID'+char(10)
  SET @v_dSql += '          			WHERE 1=1'+char(10)
  SET @v_dSql += '          			AND	  A.SITE_ID <>  A.TO_SITE_ID'+char(10)
  SET @v_dSql += '          			AND   A.SHIP_DATE BETWEEN CONVERT(DATETIME,'+char(10)
  SET @v_dSql += '' + @v_bucket_from+''+char(10)
  SET @v_dSql += ') AND CONVERT(DATETIME,'+char(10)
  SET @v_dSql += '' + @v_bucket_to+''+char(10)
  --SET @v_dSql += ') -- from to'+char(10)
  SET @v_dSql += ') '+char(10)
  SET @v_dSql += '          			GROUP BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.ITEM_ID, A.SHIP_DATE'+char(10)
  --SET @v_dSql += '          			-- production item 0 qty'+char(10)
  SET @v_dSql += '          			UNION ALL'+char(10)
  SET @v_dSql += '          			SELECT DISTINCT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID'+char(10)
  SET @v_dSql += '          				   , A.ITEM_ID AS CELL_GROUP_CODE, A.ITEM_ID AS CELL_CODE'+char(10)
  SET @v_dSql += '          				   , CONVERT(VARCHAR,A.PLAN_DATE,112) AS PLAN_DATE'+char(10)
  SET @v_dSql += '          				   , 0 AS RECEIPT_QTY'+char(10)
  SET @v_dSql += '          				   , 0 AS SHIP_OUT_QTY'+char(10)
  SET @v_dSql += '          			FROM   ' + @FORM_AMEND_TABLE+' A WITH(NOLOCK)'+char(10)
  SET @v_dSql += '          			WHERE  A.INSTANCE_ID ='+char(10)
  SET @v_dSql += '' + @v_form_instance_id+''+char(10)
  --SET @v_dSql += '               --->  UI FILTER: INSTANCE_ID'+char(10)
  --SET @v_dSql += '          			AND    A.FP_PLAN_ID IN ( '+ @FORM_PLAN_LT + ' )   --->  UI FILTER: PLAN_ID'+char(10)
  SET @v_dSql += '          			AND    A.FP_PLAN_ID IN ( '+ @FORM_PLAN_LT + ' )   '+char(10)
  SET @v_dSql += '          			AND	   A.PLAN_DATE BETWEEN CONVERT(DATETIME,'+char(10)
  SET @v_dSql += '' + @v_bucket_from+''+char(10)
  SET @v_dSql += ') AND CONVERT(DATETIME,'+char(10)
  SET @v_dSql += '' + @v_bucket_to+''+char(10)
  --SET @v_dSql += ')  --->  UI FILTER: INSTANCE_DATE ~ END_DATE'+char(10)
  SET @v_dSql += ')  '+char(10)
  SET @v_dSql += '          			AND    A.OPERATION_ID = ''F6000'''+char(10)
  SET @v_dSql += '          			AND	   A.CATEGORY_ID = ''PLAN'''+char(10)
  SET @v_dSql += '          			AND	   (A.OUT_QTY > 0 OR  A.RESULT_QTY> 0 )'+char(10)
  SET @v_dSql += '          			AND	   A.LINE_ID    != ''-'''+char(10)
  SET @v_dSql += '          	) A'+char(10)
  --SET @v_dSql += '          	INNER JOIN ('+char(10)
  --SET @v_dSql += '          		SELECT ''FORM_S_CELL_ARRIVED'' AS CATEGORY_ID, ''Cell(to be arrived)'' AS CATEGORY_NAME, 10 AS CATEGORY_ORDER, 1 AS PSI_ORDER, ''FORM'' AS SHOP_TYPE, 20 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '          		UNION ALL'+char(10)
  --SET @v_dSql += '          		SELECT ''FORM_S_CELL_REQUEST'' AS CATEGORY_ID, ''Cell Request'' AS CATEGORY_NAME, 20 AS CATEGORY_ORDER, 1 AS PSI_ORDER, ''FORM'' AS SHOP_TYPE, 20 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '          		UNION ALL'+char(10)
  --SET @v_dSql += '          		SELECT ''FORM_S_SHIPPING_REQUEST'' AS CATEGORY_ID, ''Shipping request'' AS CATEGORY_NAME, 30 AS CATEGORY_ORDER, 1 AS PSI_ORDER, ''FORM'' AS SHOP_TYPE, 20 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '          		UNION ALL'+char(10)
  --SET @v_dSql += '          		SELECT ''FORM_I_EOH'' AS CATEGORY_ID, ''EOH(Plan)'' AS CATEGORY_NAME, 100 AS CATEGORY_ORDER, 100 AS PSI_ORDER, ''FORM'' AS SHOP_TYPE, 20 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '          	) B'+char(10)
  --SET @v_dSql += '          	ON 1=1'+char(10)
  SET @v_dSql += '      	INNER JOIN #TblFP00631_TEMP B'+char(10)
  SET @v_dSql += '      	ON 1=1 AND B.PSI_ORDER != 10 AND B.SHOP_ORDER = 20 '+char(10)
  SET @v_dSql += '          	LEFT OUTER JOIN ('+char(10)
  SET @v_dSql += '        			SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.ITEM_ID, ISNULL(SUM(GOOD_QTY),0) AS BOH_QTY'+char(10)
  SET @v_dSql += '        			FROM   ('+char(10)
  --SET @v_dSql += '        					/* 특성 ERP BOH 조회 부분 */'+char(10)
  SET @v_dSql += '        					SELECT A.CUTOFF_DATE , A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.STORAGE_ID, A.FP_APPLY_OPERATION_ID, A.STOCK_TYPE, A.QTY2 AS QTY'+char(10)
  SET @v_dSql += '        							, ISNULL(WIPHOLD_YN,''N'') AS WIPHOLD_YN'+char(10)
  SET @v_dSql += '        							, CASE WHEN CONVERT(VARCHAR,A.AVAILABLE_DATE,112) <= CONVERT(VARCHAR,A.CUTOFF_DATE,112) AND  ISNULL(WIPHOLD_YN,''N'') <> ''Y'' THEN A.QTY2 ELSE NULL END AS GOOD_QTY'+char(10)
  SET @v_dSql += '        							, CASE WHEN ISNULL(WIPHOLD_YN,''N'') = ''Y'' THEN A.QTY2 ELSE NULL END AS HOLD_QTY'+char(10)
  SET @v_dSql += '        							, A.FP_APPLY_ITEM_ID AS ITEM_ID'+char(10)
  SET @v_dSql += '        							, IM.FLOW_ID , IM.LEVEL_1_CODE, IM.LEVEL_2_CODE, IM.LEVEL_2_NAME, IM.LEVEL_3_CODE, IM.LEVEL_3_NAME'+char(10)
  SET @v_dSql += '        					FROM   SCM_STOCK_H_V A WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '        					INNER HASH JOIN ( --< ITEM CODE 검색용 >--'+char(10)
  SET @v_dSql += '        					INNER HASH JOIN ( '+char(10)
  SET @v_dSql += '        							SELECT  S.COMPANY_ID , S.DIVISION_ID, S.SITE_ID , S.ITEM_ID , S.ITEM_CLASS , RIGHT(S.FLOW_ID,5) AS FLOW_ID , S.CLASS_NAME , S.LEVEL'+char(10)
  SET @v_dSql += '        									, S.LEVEL_1_CODE , S.LEVEL_1_NAME , S.LEVEL_1_ID'+char(10)
  SET @v_dSql += '        									, S.LEVEL_2_CODE , S.LEVEL_2_NAME , S.LEVEL_2_ID'+char(10)
  SET @v_dSql += '        									, S.LEVEL_3_CODE , S.LEVEL_3_NAME , S.LEVEL_3_ID'+char(10)
  SET @v_dSql += '        									, S.LEVEL_4_CODE , S.LEVEL_4_NAME , S.LEVEL_4_ID'+char(10)
  SET @v_dSql += '        									, S.LEVEL_5_CODE , S.LEVEL_5_NAME , S.LEVEL_5_ID'+char(10)
  --SET @v_dSql += '        							FROM   SCM_ITEM_M I WITH(NOLOCK), SCM_ITEM_CLASS_M S WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    							FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP S'+char(10)
  SET @v_dSql += '    							WHERE  1   = 1 '+char(10)
  --SET @v_dSql += '        							WHERE  I.ITEM_CLASS   = S.CLASS_ID'+char(10)
  --SET @v_dSql += '        							AND    I.ACTIVE_FLAG  = ''Y'''+char(10)
  --SET @v_dSql += '        							AND    S.USE_FLAG     = ''Y'''+char(10)
  SET @v_dSql += '        							AND    S.LEVEL_3_NAME = ''Cell'''+char(10)
  SET @v_dSql += '        							AND    RIGHT(S.FLOW_ID,5) IN ( ''A9000'',''A3000'' )'+char(10)
  SET @v_dSql += '        					) IM'+char(10)
  SET @v_dSql += '        					ON   1=1'+char(10)
  SET @v_dSql += '        					AND  IM.ITEM_ID     = A.FP_APPLY_ITEM_ID'+char(10)
  SET @v_dSql += '        					AND  IM.COMPANY_ID  = A.COMPANY_ID'+char(10)
  SET @v_dSql += '        					AND  IM.DIVISION_ID = A.DIVISION_ID'+char(10)
  SET @v_dSql += '        					AND  IM.SITE_ID     = A.SITE_ID'+char(10)
  --SET @v_dSql += '        					INNER HASH JOIN ( --<V: LOOKUP에 STOCK POINT 참조 >--'+char(10)
  SET @v_dSql += '        					INNER HASH JOIN #SCM_SYS_LOOKUP_TYPE_VALUE_TEMP V '+char(10)
  --SET @v_dSql += '        							SELECT  B.LOOKUP_TYPE_CODE'+char(10)
  --SET @v_dSql += '        									, B.SEGMENT1 AS SIMULATION_NAME , B.SEGMENT2 AS SITE_ID , B.SEGMENT3 AS DIVISION_ID , B.SEGMENT4 AS PLANT_ID , B.SEGMENT5 AS STOCK_POINT'+char(10)
  --SET @v_dSql += '        									, B.ATTRIBUTE1 AS STOCK_TYPE , B.ATTRIBUTE2 AS ASSY_BOH , B.ATTRIBUTE3 AS CELL_BOH, B.ATTRIBUTE4 AS PACK_BOH'+char(10)
  --SET @v_dSql += '        							FROM    SCM_SYS_LOOKUP_TYPE_M A WITH(NOLOCK), SCM_SYS_LOOKUP_VALUE  B WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '        							WHERE  A.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '        							AND    B.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '        							AND    A.LOOKUP_TYPE_CODE = B.LOOKUP_TYPE_CODE'+char(10)
  --SET @v_dSql += '        							AND    A.LOOKUP_TYPE_CODE = ''SIMULATION_BOH'''+char(10)
  --SET @v_dSql += '        							AND    B.SEGMENT1         = ''CELL_SIMULATION'''+char(10)
  --SET @v_dSql += '        					) V'+char(10)
  SET @v_dSql += '        					ON   A.SITE_ID               = V.SITE_ID'+char(10)
  SET @v_dSql += '        					AND  A.DIVISION_ID           = V.DIVISION_ID'+char(10)
  SET @v_dSql += '        					AND  A.PLANT_ID              = V.PLANT_ID'+char(10)
  SET @v_dSql += '        					AND  A.STOCK_TYPE            = V.STOCK_TYPE'+char(10)
  SET @v_dSql += '        					AND  A.STORAGE_ID            = V.STOCK_POINT'+char(10)
  --SET @v_dSql += '        					AND  V.CELL_BOH              = ''Y''         --- 특성BOH 조회 공정'+char(10)
  SET @v_dSql += '        					AND  V.CELL_BOH              = ''Y''         '+char(10)
  SET @v_dSql += '        					WHERE CUTOFF_DATE ='+char(10)
  SET @v_dSql += '' + @v_plan_date+''+char(10)
  --SET @v_dSql += '  ---> instance date'+char(10)
  --SET @v_dSql += '        					AND  A.STOCK_TYPE  = ''INVENTORY''  ---  ERP 재고'+char(10)
  SET @v_dSql += '        					AND  A.STOCK_TYPE  = ''INVENTORY''  '+char(10)
  SET @v_dSql += '        					AND  A.QTY2 > 0'+char(10)
  SET @v_dSql += '        					AND EXISTS ('+char(10)
  SET @v_dSql += '        						SELECT 1'+char(10)
  SET @v_dSql += '        						FROM   FP_INSTANCE_INFO_V VV WITH(NOLOCK)'+char(10)
  SET @v_dSql += '        						WHERE  VV.INSTANCE_ID ='+char(10)
  SET @v_dSql += '' + @v_form_instance_id+''+char(10)
  SET @v_dSql += '        						AND    A.COMPANY_ID   = VV.COMPANY_ID'+char(10)
  SET @v_dSql += '        						AND    A.DIVISION_ID  = VV.DIVISION_ID'+char(10)
  SET @v_dSql += '        						AND    A.SITE_ID      = VV.SITE_ID'+char(10)
  SET @v_dSql += '        					)'+char(10)
  SET @v_dSql += '        					UNION ALL'+char(10)
  --SET @v_dSql += '        					/* 특성 MES BOH 조회'+char(10)
  --SET @v_dSql += '        					** 특이사항: P5000 아이템코드는 CELL코드로 변경해서 반영해준다.  */'+char(10)
  SET @v_dSql += '        					SELECT A.CUTOFF_DATE , A.COMPANY_ID , A.DIVISION_ID , A.SITE_ID , A.PLANT_ID , A.STORAGE_ID, A.FP_APPLY_OPERATION_ID AS OPERATION_ID'+char(10)
  SET @v_dSql += '        							, A.STOCK_TYPE'+char(10)
  SET @v_dSql += '        							, (CASE WHEN BB.CHILD_ITEM_ID IS NOT NULL THEN FP_APPLY_WIPQTY * BB.BOM_RATE ELSE FP_APPLY_WIPQTY END) AS QTY'+char(10)
  SET @v_dSql += '        							, ISNULL(WIPHOLD_YN,''N'') AS WIPHOLD_YN'+char(10)
  SET @v_dSql += '        							, CASE WHEN CONVERT(VARCHAR,A.AVAILABLE_DATE,112) <= CONVERT(VARCHAR,A.CUTOFF_DATE,112) AND  ISNULL(WIPHOLD_YN,''N'') <> ''Y'''+char(10)
  SET @v_dSql += '              							 THEN  CASE WHEN BB.CHILD_ITEM_ID IS NOT NULL THEN FP_APPLY_WIPQTY * BB.BOM_RATE ELSE FP_APPLY_WIPQTY END'+char(10)
  SET @v_dSql += '              							 ELSE NULL END AS GOOD_QTY'+char(10)
  SET @v_dSql += '        							, CASE WHEN ISNULL(WIPHOLD_YN,''N'') = ''Y'''+char(10)
  SET @v_dSql += '              							 THEN (CASE WHEN BB.CHILD_ITEM_ID IS NOT NULL THEN FP_APPLY_WIPQTY * BB.BOM_RATE ELSE FP_APPLY_WIPQTY END)'+char(10)
  SET @v_dSql += '              							 ELSE NULL END AS HOLD_QTY'+char(10)
  SET @v_dSql += '        							, ISNULL(BB.CHILD_ITEM_ID, A.FP_APPLY_ITEM_ID) AS ITEM_ID'+char(10)
  SET @v_dSql += '        							, IM.FLOW_ID , IM.LEVEL_1_CODE, IM.LEVEL_2_CODE, IM.LEVEL_2_NAME, IM.LEVEL_3_CODE, IM.LEVEL_3_NAME'+char(10)
  SET @v_dSql += '        					FROM   SCM_STOCK_H_V A WITH(NOLOCK)'+char(10)
  SET @v_dSql += '        					INNER HASH JOIN'+char(10)
  --SET @v_dSql += '        							( --<IM: ITEM CODE 검색용 >--'+char(10)
  SET @v_dSql += '        							( '+char(10)
  SET @v_dSql += '        							SELECT  S.COMPANY_ID , S.DIVISION_ID, S.SITE_ID , S.ITEM_ID , S.ITEM_CLASS , RIGHT(S.FLOW_ID,5) AS FLOW_ID , S.CLASS_NAME , S.LEVEL'+char(10)
  SET @v_dSql += '        									, S.LEVEL_1_CODE , S.LEVEL_1_NAME , S.LEVEL_1_ID'+char(10)
  SET @v_dSql += '        									, S.LEVEL_2_CODE , S.LEVEL_2_NAME , S.LEVEL_2_ID'+char(10)
  SET @v_dSql += '        									, S.LEVEL_3_CODE , S.LEVEL_3_NAME , S.LEVEL_3_ID'+char(10)
  SET @v_dSql += '        									, S.LEVEL_4_CODE , S.LEVEL_4_NAME , S.LEVEL_4_ID'+char(10)
  SET @v_dSql += '        									, S.LEVEL_5_CODE , S.LEVEL_5_NAME , S.LEVEL_5_ID'+char(10)
  --SET @v_dSql += '        							FROM    SCM_ITEM_M I WITH(NOLOCK), SCM_ITEM_CLASS_M S WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    							FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP S'+char(10)
  SET @v_dSql += '    							WHERE  1   = 1 '+char(10)
  --SET @v_dSql += '        							WHERE  I.ITEM_CLASS   = S.CLASS_ID'+char(10)
  --SET @v_dSql += '        							AND    I.ACTIVE_FLAG  = ''Y'''+char(10)
  --SET @v_dSql += '        							AND    S.USE_FLAG     = ''Y'''+char(10)
  SET @v_dSql += '        							AND    S.LEVEL_3_NAME IN ( ''Cell'' , ''Module Automotive Assembly'' )'+char(10)
  SET @v_dSql += '        							AND    RIGHT(S.FLOW_ID,5) IN ( ''A9000'',''A3000'',''P5000'' )'+char(10)
  SET @v_dSql += '        					) IM'+char(10)
  SET @v_dSql += '        					ON   1=1'+char(10)
  SET @v_dSql += '        					AND  IM.ITEM_ID     = A.FP_APPLY_ITEM_ID'+char(10)
  SET @v_dSql += '        					AND  IM.COMPANY_ID  = A.COMPANY_ID'+char(10)
  SET @v_dSql += '        					AND  IM.DIVISION_ID = A.DIVISION_ID'+char(10)
  SET @v_dSql += '        					AND  IM.SITE_ID     = A.SITE_ID'+char(10)
  --SET @v_dSql += '        					INNER HASH JOIN ( --<V: LOOKUP에 STOCK POINT 참조 >--'+char(10)
  SET @v_dSql += '        					INNER HASH JOIN #SCM_SYS_LOOKUP_TYPE_VALUE_TEMP V '+char(10)
  --SET @v_dSql += '        							SELECT  B.LOOKUP_TYPE_CODE'+char(10)
  --SET @v_dSql += '        									, B.SEGMENT1 AS SIMULATION_NAME , B.SEGMENT2 AS SITE_ID , B.SEGMENT3 AS DIVISION_ID , B.SEGMENT4 AS PLANT_ID , B.SEGMENT5 AS STOCK_POINT'+char(10)
  --SET @v_dSql += '        									, B.ATTRIBUTE1 AS STOCK_TYPE , B.ATTRIBUTE2 AS ASSY_BOH , B.ATTRIBUTE3 AS CELL_BOH, B.ATTRIBUTE4 AS PACK_BOH'+char(10)
  --SET @v_dSql += '        							FROM    SCM_SYS_LOOKUP_TYPE_M A WITH(NOLOCK), SCM_SYS_LOOKUP_VALUE  B WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '        							WHERE  A.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '        							AND    B.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '        							AND    A.LOOKUP_TYPE_CODE = B.LOOKUP_TYPE_CODE'+char(10)
  --SET @v_dSql += '        							AND    A.LOOKUP_TYPE_CODE = ''SIMULATION_BOH'''+char(10)
  --SET @v_dSql += '        							AND    B.SEGMENT1         = ''CELL_SIMULATION'''+char(10)
  --SET @v_dSql += '        					) V'+char(10)
  SET @v_dSql += '        					ON   A.SITE_ID               = V.SITE_ID'+char(10)
  SET @v_dSql += '        					AND  A.DIVISION_ID           = V.DIVISION_ID'+char(10)
  SET @v_dSql += '        					AND  A.PLANT_ID              = V.PLANT_ID'+char(10)
  SET @v_dSql += '        					AND  A.STOCK_TYPE            = V.STOCK_TYPE'+char(10)
  SET @v_dSql += '        					AND  A.FP_APPLY_OPERATION_ID = V.STOCK_POINT'+char(10)
  --SET @v_dSql += '        					AND  V.CELL_BOH              = ''Y''         --->  BOH타입에 따라서 조건 변경해줘야 함.'+char(10)
  SET @v_dSql += '        					AND  V.CELL_BOH              = ''Y''         '+char(10)
  --SET @v_dSql += '        					LEFT OUTER HASH JOIN ( --<BB: P5000 ITEM은 CELL코드로 변환: ALT_PRIORITY1순위로 가져온다. >--'+char(10)
  SET @v_dSql += '        					LEFT OUTER HASH JOIN ( '+char(10)
  SET @v_dSql += '        							SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID , A.PARENT_ITEM_ID , A.CHILD_ITEM_ID , A.ALT_PRIORITY'+char(10)
  SET @v_dSql += '        							     , A.CHILD_QTY/A.PARENT_QTY AS BOM_RATE'+char(10)
  SET @v_dSql += '        							FROM	SCM_BOM_M A WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '        							INNER HASH JOIN ( --: 자품목이 CELL 조건 필터'+char(10)
  SET @v_dSql += '        							INNER HASH JOIN ( '+char(10)
  SET @v_dSql += '        									SELECT CC.COMPANY_ID , CC.DIVISION_ID , CC.SITE_ID, CC.ITEM_ID , CC.ITEM_CLASS , CC.LEVEL_3_CODE, CC.LEVEL_3_NAME, CC.FLOW_ID'+char(10)
  --SET @v_dSql += '        									FROM   SCM_ITEM_M CC WITH(NOLOCK), SCM_ITEM_CLASS_M DD WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    							FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP CC'+char(10)
  SET @v_dSql += '        									WHERE 1=1'+char(10)
  --SET @v_dSql += '        									AND  CC.ITEM_CLASS    = DD.CLASS_ID'+char(10)
  --SET @v_dSql += '        									AND  CC.ACTIVE_FLAG   = ''Y'''+char(10)
  --SET @v_dSql += '        									AND  DD.USE_FLAG      = ''Y'''+char(10)
  SET @v_dSql += '        									AND  CC.LEVEL_3_NAME  = ''Cell'''+char(10)
  SET @v_dSql += '        									AND  RIGHT(ISNULL(CC.FLOW_ID,''Z''),5)  IN (''A9000'', ''A3000'' )'+char(10)
  SET @v_dSql += '        							) EE'+char(10)
  SET @v_dSql += '        							ON   1=1'+char(10)
  SET @v_dSql += '        							AND  A.COMPANY_ID  = EE.COMPANY_ID'+char(10)
  SET @v_dSql += '        							AND  A.DIVISION_ID = EE.DIVISION_ID'+char(10)
  SET @v_dSql += '        							AND  A.SITE_ID     = EE.SITE_ID'+char(10)
  SET @v_dSql += '        							AND  A.CHILD_ITEM_ID = EE.ITEM_ID'+char(10)
  SET @v_dSql += '        							WHERE 1=1'+char(10)
  SET @v_dSql += '        							AND   CONVERT(NVARCHAR(8),A.EFF_END_DATE,112)   >'+char(10)
  SET @v_dSql += '' + @v_plan_date+''+char(10)
  --SET @v_dSql += ' --- INSTANCE_DATE'+char(10)
  SET @v_dSql += '        							AND   CONVERT(NVARCHAR(8),A.EFF_START_DATE,112) <='+char(10)
  SET @v_dSql += '' + @v_plan_date+''+char(10)
  --SET @v_dSql += '  --- INSTANCE_DATE'+char(10)
  SET @v_dSql += '        							AND   ISNULL(A.ALT_PRIORITY,1) = 1'+char(10)
  SET @v_dSql += '        					) BB'+char(10)
  SET @v_dSql += '        					ON  1=1'+char(10)
  SET @v_dSql += '        					AND  A.SITE_ID          = BB.SITE_ID'+char(10)
  SET @v_dSql += '        					AND  A.DIVISION_ID      = BB.DIVISION_ID'+char(10)
  SET @v_dSql += '        					AND  A.PLANT_ID         = BB.PLANT_ID'+char(10)
