  SET @v_dSql += '                		 , B.DATE_ID AS PLAN_DATE, A.TOP_ITEM_ID, B.YEAR+B.MONTH AS MONTH'+char(10)
  SET @v_dSql += '                		 , A.ITEM_ID AS CELL_GROUP_CODE'+char(10)
  SET @v_dSql += '                  FROM   MAIN_CELL_REL_P A WITH(NOLOCK), SCM_SYS_CALENDAR_M B WITH(NOLOCK)'+char(10)
  SET @v_dSql += '                  WHERE  1=1'+char(10)
  SET @v_dSql += '                  AND'+char(10)
  SET @v_dSql += '' + @v_is_rel_assy+''+char(10)
  --SET @v_dSql += ' = ''Y'' -- release plan'+char(10)
  SET @v_dSql += ' = ''Y'' '+char(10)
  SET @v_dSql += '                  AND    B.DATE_ID BETWEEN CONVERT(DATETIME,'+char(10)
  SET @v_dSql += '' + @v_bucket_from+''+char(10)
  SET @v_dSql += ') AND CONVERT(DATETIME,'+char(10)
  SET @v_dSql += '' + @v_bucket_to+''+char(10)
  --SET @v_dSql += ') -- START DATE ~ END DATE'+char(10)
