  SET @v_dSql += ' THEN ''81'' ELSE A.DIVISION_ID END )'+char(10)
  SET @v_dSql += '              ) A'+char(10)
  SET @v_dSql += '              LEFT OUTER HASH JOIN MAIN_CELL_REL_P B WITH(NOLOCK)'+char(10)
  SET @v_dSql += '              ON  A.COMPANY_ID      = B.COMPANY_ID'+char(10)
  SET @v_dSql += '              AND A.DIVISION_ID     = B.DIVISION_ID'+char(10)
  SET @v_dSql += '              AND A.CATEGORY_ID     = B.CATEGORY_ID'+char(10)
  SET @v_dSql += '              AND A.SITE_ID         = B.SITE_ID'+char(10)
  SET @v_dSql += '              AND A.PLANT_ID        = B.PLANT_ID'+char(10)
  SET @v_dSql += '              AND A.ITEM_ID         = B.ITEM_ID'+char(10)
  SET @v_dSql += '              AND A.OPERATION_ID    = B.OPERATION_ID'+char(10)
  SET @v_dSql += '              AND A.FACTORY_ID      = B.FACTORY_ID'+char(10)
  SET @v_dSql += '              AND A.LOCATION        = B.LOCATION'+char(10)
  SET @v_dSql += '              AND A.PRODUCTION_TYPE = B.PRODUCTION_TYPE'+char(10)
  SET @v_dSql += '              AND A.MARKET          = B.MARKET'+char(10)
  SET @v_dSql += '              AND A.LINE_ID         = B.LINE_ID'+char(10)
  SET @v_dSql += '              AND A.ELECTRODE_TYPE  = B.ELECTRODE_TYPE'+char(10)
  SET @v_dSql += '              AND A.PLAN_DATE       = B.PLAN_DATE'+char(10)
  SET @v_dSql += '              AND A.TOP_ITEM_ID     = B.TOP_ITEM_ID'+char(10)
  SET @v_dSql += '      		) A'+char(10)
  SET @v_dSql += '      		LEFT OUTER JOIN SCM_YIELD_M AS D1 WITH(NOLOCK)'+char(10)
  SET @v_dSql += '      		ON     A.COMPANY_ID     = D1.COMPANY_ID'+char(10)
  SET @v_dSql += '      		AND    A.DIVISION_ID    = D1.DIVISION_ID'+char(10)
  SET @v_dSql += '      		AND    A.SITE_ID        = D1.SITE_ID'+char(10)
  SET @v_dSql += '      		AND    A.PLANT_ID       = D1.PLANT_ID'+char(10)
  SET @v_dSql += '      		AND    A.FACTORY_ID     = D1.FACTORY_ID'+char(10)
  SET @v_dSql += '      		AND    A.OPERATION_ID   = D1.OPERATION_ID'+char(10)
  SET @v_dSql += '      		AND    A.LINE_ID        = D1.LINE_ID'+char(10)
  SET @v_dSql += '      		AND    A.ITEM_ID        = D1.ITEM_ID'+char(10)
  SET @v_dSql += '      		AND    A.MONTH          = D1.MONTH'+char(10)
  SET @v_dSql += '      		LEFT OUTER JOIN SCM_YIELD_EXCEPT_M AS D2 WITH(NOLOCK)'+char(10)
  SET @v_dSql += '      		ON     A.COMPANY_ID     = D2.COMPANY_ID'+char(10)
  SET @v_dSql += '      		AND    A.DIVISION_ID    = D2.DIVISION_ID'+char(10)
  SET @v_dSql += '      		AND    A.SITE_ID        = D2.SITE_ID'+char(10)
  SET @v_dSql += '      		AND    A.PLANT_ID       = D2.PLANT_ID'+char(10)
  SET @v_dSql += '      		AND    A.FACTORY_ID     = D2.FACTORY_ID'+char(10)
  SET @v_dSql += '      		AND    A.OPERATION_ID   = D2.OPERATION_ID'+char(10)
  SET @v_dSql += '      		AND    A.LINE_ID        = D2.LINE_ID'+char(10)
  SET @v_dSql += '      		AND    A.ITEM_ID        = D2.ITEM_ID'+char(10)
  SET @v_dSql += '      		AND    A.PLAN_DATE     >= D2.START_TIME'+char(10)
  SET @v_dSql += '      		AND    A.PLAN_DATE     <= D2.END_TIME'+char(10)
  SET @v_dSql += '      		AND    D2.ACTIVE_FLAG   = ''Y'''+char(10)
  SET @v_dSql += '      		INNER HASH JOIN ('+char(10)
  SET @v_dSql += '    					SELECT DISTINCT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.ITEM_ID'+char(10)
  SET @v_dSql += '        						,(CASE WHEN LEFT(A.FLOW_ID,5) = ''A9000'' AND ISNULL(A.LEVEL_4_NAME, ''-'') = ''-'' THEN A.LEVEL_3_NAME'+char(10)
  SET @v_dSql += '        						       WHEN LEFT(A.FLOW_ID,5) = ''A9000'' THEN ISNULL(A.LEVEL_4_NAME, ''-'')'+char(10)
  SET @v_dSql += '        							     ELSE A.LEVEL_3_NAME END) AS ITEM_TYPE'+char(10)
  SET @v_dSql += '        						,ISNULL(A.NICK_NAME,''-'') AS NICK_NAME, ISNULL(A.PACK_PRODUCT_GROUP_CODE,''-'') AS PJT_GROUP_NAME'+char(10)
  --SET @v_dSql += '    					FROM   SCM_ITEM_M A WITH(NOLOCK), SCM_ITEM_CLASS_M C WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    							FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP A'+char(10)
  SET @v_dSql += '    							WHERE  1   = 1 '+char(10)
  --SET @v_dSql += '    					WHERE  A.ITEM_CLASS  = C.CLASS_ID'+char(10)
  --SET @v_dSql += '    					AND    A.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '    					AND    C.USE_FLAG    = ''Y'''+char(10)
  SET @v_dSql += '      		) E'+char(10)
  SET @v_dSql += '      		ON     A.COMPANY_ID     = E.COMPANY_ID'+char(10)
  SET @v_dSql += '      		AND    A.DIVISION_ID    = E.DIVISION_ID'+char(10)
  SET @v_dSql += '      		AND    A.SITE_ID        = E.SITE_ID'+char(10)
  SET @v_dSql += '      		AND    A.ITEM_ID        = E.ITEM_ID'+char(10)
  SET @v_dSql += ' ' +@opt_10assy_item_id +' '+''+char(10)--AND    A.ITEM_ID LIKE '%' + #ASSY_ITEM_ID# + '%'
  SET @v_dSql += ' ' +@opt_11assy_nick_name +' '+''+char(10)--AND    E.NICK_NAME LIKE '%' + #ASSY_NICK_NAME# + '%'
  SET @v_dSql += '      		GROUP BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.OPERATION_ID, A.PRODUCTION_TYPE, A.MARKET, A.LINE_ID, A.PLAN_DATE'+char(10)
  SET @v_dSql += '      			   , A.CELL_GROUP_CODE, A.ITEM_ID, E.NICK_NAME, E.ITEM_TYPE'+char(10)
  SET @v_dSql += '      	) A'+char(10)
  --SET @v_dSql += '      	INNER JOIN ('+char(10)
  --SET @v_dSql += '      		SELECT ''CELL_P_OUT_CELL'' AS CATEGORY_ID, ''Plan(Out)_CELL'' AS CATEGORY_NAME, 100 AS CATEGORY_ORDER, 10 AS PSI_ORDER, ''CELL'' AS SHOP_TYPE, 30 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '      		UNION ALL'+char(10)
  --SET @v_dSql += '      		SELECT ''CELL_P_OUT_UOM'' AS CATEGORY_ID, ''Plan(Out)_UOM'' AS CATEGORY_NAME, 110 AS CATEGORY_ORDER, 10 AS PSI_ORDER, ''CELL'' AS SHOP_TYPE, 30 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '      		UNION ALL'+char(10)
  --SET @v_dSql += '      		SELECT ''CELL_P_RESULT_CELL'' AS CATEGORY_ID, ''Result_CELL'' AS CATEGORY_NAME, 120 AS CATEGORY_ORDER, 10 AS PSI_ORDER, ''CELL'' AS SHOP_TYPE, 30 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '      		UNION ALL'+char(10)
  --SET @v_dSql += '      		SELECT ''CELL_P_RESULT_UOM'' AS CATEGORY_ID, ''Result_UOM'' AS CATEGORY_NAME, 140 AS CATEGORY_ORDER, 10 AS PSI_ORDER, ''CELL'' AS SHOP_TYPE, 30 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '      		UNION ALL'+char(10)
  --SET @v_dSql += '      		SELECT ''CELL_P_YIELD'' AS CATEGORY_ID, ''Yield (%)'' AS CATEGORY_NAME, 150 AS CATEGORY_ORDER, 10 AS PSI_ORDER, ''CELL'' AS SHOP_TYPE, 30 AS SHOP_ORDER'+char(10)
  --SET @v_dSql += '      	) B'+char(10)
  --SET @v_dSql += '      	ON 1=1'+char(10)
  SET @v_dSql += '      	INNER JOIN #TblFP00631_TEMP B'+char(10)
  SET @v_dSql += '      	ON 1=1 AND B.PSI_ORDER = 10 AND B.SHOP_ORDER = 30 '+char(10)
  SET @v_dSql += '      	LEFT OUTER JOIN ('+char(10)
  SET @v_dSql += '    			SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.ITEM_ID, ISNULL(SUM(GOOD_QTY),0) AS BOH_QTY'+char(10)
  SET @v_dSql += '    			FROM   ('+char(10)
  --SET @v_dSql += '    					/* 조립 ERP BOH 조회 부분 */'+char(10)
  SET @v_dSql += '    					SELECT A.CUTOFF_DATE , A.COMPANY_ID , A.DIVISION_ID , A.SITE_ID , A.PLANT_ID , A.STORAGE_ID, A.FP_APPLY_OPERATION_ID'+char(10)
  SET @v_dSql += '    						 , A.STOCK_TYPE'+char(10)
  SET @v_dSql += '    						 , A.QTY2 AS QTY'+char(10)
  SET @v_dSql += '    						 , ISNULL(WIPHOLD_YN,''N'') AS WIPHOLD_YN'+char(10)
  SET @v_dSql += '    						 , CASE WHEN CONVERT(VARCHAR,A.AVAILABLE_DATE,112) <= CONVERT(VARCHAR,A.CUTOFF_DATE,112) AND ISNULL(WIPHOLD_YN,''N'') <> ''Y'' THEN A.QTY2 ELSE NULL END AS GOOD_QTY'+char(10)
  SET @v_dSql += '    						 , CASE WHEN ISNULL(WIPHOLD_YN,''N'') = ''Y'' THEN A.QTY2 ELSE NULL END AS HOLD_QTY'+char(10)
  SET @v_dSql += '    						 , A.FP_APPLY_ITEM_ID AS ITEM_ID'+char(10)
  SET @v_dSql += '    						 , IM.FLOW_ID, IM.LEVEL_1_CODE, IM.LEVEL_2_CODE, IM.LEVEL_2_NAME, IM.LEVEL_3_CODE, IM.LEVEL_3_NAME'+char(10)
  SET @v_dSql += '    					FROM   SCM_STOCK_H_V A WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '    					INNER HASH JOIN ( --< ITEM CODE 검색용 >--'+char(10)
  SET @v_dSql += '    					INNER HASH JOIN ( '+char(10)
  SET @v_dSql += '    							SELECT  S.COMPANY_ID , S.DIVISION_ID, S.SITE_ID , S.ITEM_ID , S.ITEM_CLASS , RIGHT(S.FLOW_ID,5) AS FLOW_ID , S.CLASS_NAME , S.LEVEL'+char(10)
  SET @v_dSql += '    									, S.LEVEL_1_CODE , S.LEVEL_1_NAME , S.LEVEL_1_ID'+char(10)
  SET @v_dSql += '    									, S.LEVEL_2_CODE , S.LEVEL_2_NAME , S.LEVEL_2_ID'+char(10)
  SET @v_dSql += '    									, S.LEVEL_3_CODE , S.LEVEL_3_NAME , S.LEVEL_3_ID'+char(10)
  SET @v_dSql += '    									, S.LEVEL_4_CODE , S.LEVEL_4_NAME , S.LEVEL_4_ID'+char(10)
  SET @v_dSql += '    									, S.LEVEL_5_CODE , S.LEVEL_5_NAME , S.LEVEL_5_ID'+char(10)
  --SET @v_dSql += '    							FROM   SCM_ITEM_M I WITH(NOLOCK), SCM_ITEM_CLASS_M S WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    							FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP S'+char(10)
  SET @v_dSql += '    							WHERE  1   = 1 '+char(10)
  --SET @v_dSql += '    							WHERE  I.ITEM_CLASS   = S.CLASS_ID'+char(10)
  --SET @v_dSql += '    							AND    I.ACTIVE_FLAG  = ''Y'''+char(10)
  --SET @v_dSql += '    							AND    S.USE_FLAG     = ''Y'''+char(10)
  SET @v_dSql += '    							AND    S.LEVEL_3_NAME = ''Cell'''+char(10)
  SET @v_dSql += '    							AND    RIGHT(S.FLOW_ID,5) IN ( ''A9000'',''A3000'' )'+char(10)
  SET @v_dSql += '    					) IM'+char(10)
  SET @v_dSql += '    					ON   1=1'+char(10)
  SET @v_dSql += '    					AND  IM.ITEM_ID     = A.FP_APPLY_ITEM_ID'+char(10)
  SET @v_dSql += '    					AND  IM.COMPANY_ID  = A.COMPANY_ID'+char(10)
  SET @v_dSql += '    					AND  IM.DIVISION_ID = A.DIVISION_ID'+char(10)
  SET @v_dSql += '    					AND  IM.SITE_ID     = A.SITE_ID'+char(10)
  --SET @v_dSql += '    					INNER HASH JOIN ( --<V: LOOKUP에 STOCK POINT 참조 >--'+char(10)
  SET @v_dSql += '    					INNER HASH JOIN #SCM_SYS_LOOKUP_TYPE_VALUE_TEMP V '+char(10)
  --SET @v_dSql += '    							SELECT B.LOOKUP_TYPE_CODE'+char(10)
  --SET @v_dSql += '    									 , B.SEGMENT1 AS SIMULATION_NAME , B.SEGMENT2 AS SITE_ID , B.SEGMENT3 AS DIVISION_ID , B.SEGMENT4 AS PLANT_ID , B.SEGMENT5 AS STOCK_POINT'+char(10)
  --SET @v_dSql += '    									 , B.ATTRIBUTE1 AS STOCK_TYPE , B.ATTRIBUTE2 AS ASSY_BOH , B.ATTRIBUTE3 AS CELL_BOH, B.ATTRIBUTE4 AS PACK_BOH'+char(10)
  --SET @v_dSql += '    							FROM   SCM_SYS_LOOKUP_TYPE_M A WITH(NOLOCK), SCM_SYS_LOOKUP_VALUE  B WITH(NOLOCK)'+char(10)
  --SET @v_dSql += '    							WHERE  A.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '    							AND    B.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '    							AND    A.LOOKUP_TYPE_CODE = B.LOOKUP_TYPE_CODE'+char(10)
  --SET @v_dSql += '    							AND    A.LOOKUP_TYPE_CODE = ''SIMULATION_BOH'''+char(10)
  --SET @v_dSql += '    							AND    B.SEGMENT1         = ''CELL_SIMULATION'''+char(10)
  --SET @v_dSql += '    					) V'+char(10)
  SET @v_dSql += '    					ON   A.SITE_ID               = V.SITE_ID'+char(10)
  SET @v_dSql += '    					AND  A.DIVISION_ID           = V.DIVISION_ID'+char(10)
  SET @v_dSql += '    					AND  A.PLANT_ID              = V.PLANT_ID'+char(10)
  SET @v_dSql += '    					AND  A.STOCK_TYPE            = V.STOCK_TYPE'+char(10)
  SET @v_dSql += '    					AND  A.STORAGE_ID            = V.STOCK_POINT'+char(10)
  --SET @v_dSql += '    					AND  V.ASSY_BOH              = ''Y''     --->  BOH 타입에 따라서 조건 변경해줘야 함.'+char(10)
  SET @v_dSql += '    					AND  V.ASSY_BOH              = ''Y''     '+char(10)
  SET @v_dSql += '    					WHERE  CUTOFF_DATE ='+char(10)
  SET @v_dSql += '' + @v_plan_date+''+char(10)
  --SET @v_dSql += '  ---> instance date'+char(10)
  --SET @v_dSql += '    					AND  A.STOCK_TYPE  = ''INVENTORY''  ---  ERP 재고'+char(10)
  SET @v_dSql += '    					AND  A.STOCK_TYPE  = ''INVENTORY''  '+char(10)
  SET @v_dSql += '    					AND EXISTS ('+char(10)
  SET @v_dSql += '    						SELECT 1'+char(10)
