  SET @v_dSql += '          			, ''DATA'' AS DATA_TYPE'+char(10)
  ---- REMAINED SCRIPT (PLEASE CONVERT THIS MANUALLY----
  SET @v_dSql += @BUCKET_SCRIPT_PART8
  --SET @v_dSql += '
