  SET @v_dSql += '        							, CASE WHEN CONVERT(VARCHAR,A.AVAILABLE_DATE,112) <= CONVERT(VARCHAR,A.CUTOFF_DATE,112) AND ISNULL(WIPHOLD_YN,''N'') <> ''Y'' THEN A.FP_APPLY_WIPQTY ELSE NULL END AS GOOD_QTY'+char(10)
  SET @v_dSql += '        							, CASE WHEN ISNULL(WIPHOLD_YN,''N'') = ''Y''  THEN A.FP_APPLY_WIPQTY ELSE NULL END AS HOLD_QTY'+char(10)
