  --SET @v_dSql += '            			-- 활성화재고'+char(10)
  SET @v_dSql += '            			UNION ALL'+char(10)
  SET @v_dSql += '                  SELECT A.CUTOFF_DATE, A.COMPANY_ID , A.DIVISION_ID , A.SITE_ID , A.PLANT_ID, NULL AS STORAGE_ID , NULL AS OPERATION_ID'+char(10)
  SET @v_dSql += '            							, NULL AS STOCK_TYPE'+char(10)
