  SET @v_dSql += '            							, NULL AS HOLD_QTY'+char(10)
  SET @v_dSql += '            							, A.ITEM_ID'+char(10)
  SET @v_dSql += '            							, NULL AS FLOW_ID, NULL AS LEVEL_1_CODE, NULL AS LEVEL_2_CODE, NULL AS LEVEL_2_NAME, NULL AS LEVEL_3_CODE, NULL AS LEVEL_3_NAME'+char(10)
  SET @v_dSql += '                  FROM   SCM_AGING_STOCK_H A WITH(NOLOCK)'+char(10)
  SET @v_dSql += '                  WHERE  CONVERT(VARCHAR(8), A.CUTOFF_DATE, 112) ='+char(10)
  SET @v_dSql += '' + @v_plan_date+''+char(10)
  SET @v_dSql += '                  AND EXISTS ('+char(10)
  SET @v_dSql += '                      SELECT 1'+char(10)
  SET @v_dSql += '                      FROM   FP_INSTANCE_INFO_V VV WITH(NOLOCK)'+char(10)
  SET @v_dSql += '                      WHERE  VV.INSTANCE_ID ='+char(10)
  SET @v_dSql += '' + @v_assy_instance_id+''+char(10)
  SET @v_dSql += '                      AND    A.COMPANY_ID   = VV.COMPANY_ID'+char(10)
  SET @v_dSql += '                      AND    A.DIVISION_ID  = VV.DIVISION_ID'+char(10)
  SET @v_dSql += '                      AND    A.SITE_ID      = VV.SITE_ID'+char(10)
  SET @v_dSql += '                      AND    A.PLANT_ID     = VV.PLANT_ID'+char(10)
  SET @v_dSql += '                  )'+char(10)
  SET @v_dSql += '        			) A'+char(10)
  SET @v_dSql += '        			WHERE 1=1'+char(10)
  SET @v_dSql += '        			GROUP BY A.COMPANY_ID , A.DIVISION_ID , A.SITE_ID , A.PLANT_ID, A.ITEM_ID'+char(10)
  SET @v_dSql += '          	) C'+char(10)
  SET @v_dSql += '          	ON  A.COMPANY_ID  = C.COMPANY_ID'+char(10)
  SET @v_dSql += '          	AND A.DIVISION_ID = C.DIVISION_ID'+char(10)
  SET @v_dSql += '          	AND A.SITE_ID     = C.SITE_ID'+char(10)
  SET @v_dSql += '          	AND A.PLANT_ID    = C.PLANT_ID'+char(10)
  SET @v_dSql += '          	AND A.ITEM_ID     = C.ITEM_ID'+char(10)
  SET @v_dSql += '          	INNER JOIN ('+char(10)
  SET @v_dSql += '          			SELECT CC.COMPANY_ID, CC.DIVISION_ID, CC.SITE_ID, CC.ITEM_ID, CC.ITEM_CLASS, CC.LEVEL_3_CODE, CC.LEVEL_3_NAME, CC.FLOW_ID, CC.NICK_NAME'+char(10)
  SET @v_dSql += '                    ,(CASE WHEN LEFT(CC.FLOW_ID,5) = ''A9000'' AND ISNULL(CC.LEVEL_4_NAME, ''-'') = ''-'' THEN CC.LEVEL_3_NAME'+char(10)
  SET @v_dSql += '                           WHEN LEFT(CC.FLOW_ID,5) = ''A9000'' THEN ISNULL(CC.LEVEL_4_NAME, ''-'')'+char(10)
  SET @v_dSql += '                           ELSE CC.LEVEL_3_NAME END) AS ITEM_TYPE'+char(10)
  --SET @v_dSql += '          			FROM   SCM_ITEM_M CC WITH(NOLOCK), SCM_ITEM_CLASS_M DD WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    							FROM   #SCM_ITEM_M_SCM_ITEM_CLASS_M_TEMP CC'+char(10)
  SET @v_dSql += '          			WHERE  1=1'+char(10)
  --SET @v_dSql += '          			AND    CC.ITEM_CLASS  = DD.CLASS_ID'+char(10)
  --SET @v_dSql += '          			AND    CC.ACTIVE_FLAG = ''Y'''+char(10)
  --SET @v_dSql += '          			AND    DD.USE_FLAG    = ''Y'''+char(10)
  SET @v_dSql += '          			AND    LEFT(ISNULL(CC.FLOW_ID,''Z''),5) IN (''A9000'')'+char(10)
  SET @v_dSql += '          			AND    CC.LEVEL_3_NAME = ''Cell'''+char(10)
  SET @v_dSql += ' ' +@opt_18assy_item_id +' '+''+char(10)--AND    CC.ITEM_ID LIKE '%' + #ASSY_ITEM_ID# + '%'
  SET @v_dSql += ' ' +@opt_19assy_nick_name +' '+''+char(10)--AND    CC.NICK_NAME LIKE '%' + #ASSY_NICK_NAME# + '%'
  SET @v_dSql += '          	) EE'+char(10)
  SET @v_dSql += '          	ON   1=1'+char(10)
  SET @v_dSql += '          	AND  A.COMPANY_ID  = EE.COMPANY_ID'+char(10)
  SET @v_dSql += '          	AND  A.DIVISION_ID = EE.DIVISION_ID'+char(10)
  SET @v_dSql += '          	AND  A.SITE_ID     = EE.SITE_ID'+char(10)
  SET @v_dSql += '          	AND  A.ITEM_ID     = EE.ITEM_ID'+char(10)
  SET @v_dSql += '          	GROUP BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID'+char(10)
  SET @v_dSql += '          			, A.CELL_GROUP_CODE, ISNULL(C.BOH_QTY,0), EE.ITEM_TYPE'+char(10)
  SET @v_dSql += '          			, B.CATEGORY_ID, B.CATEGORY_NAME, B.CATEGORY_ORDER, B.PSI_ORDER, B.SHOP_TYPE, B.SHOP_ORDER'+char(10)
  SET @v_dSql += '          			, A.PRODUCTION_TYPE, A.MARKET'+char(10)
  SET @v_dSql += '        ) A'+char(10)
  SET @v_dSql += '        GROUP BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.PRODUCTION_TYPE, A.MARKET'+char(10)
  SET @v_dSql += '          			, A.CELL_GROUP_CODE, A.CELL_CODE, A.CELL_NICK_NAME, A.ITEM_TYPE'+char(10)
  SET @v_dSql += '          			, A.CATEGORY_ID, A.CATEGORY_NAME, A.CATEGORY_ORDER, A.PSI_ORDER, A.SHOP_TYPE, A.SHOP_ORDER'+char(10)
  SET @v_dSql += '          			, A.DATA_TYPE'+char(10)
  SET @v_dSql += '      )'+char(10)
  SET @v_dSql += '      SELECT A.*'+char(10)
  --SET @v_dSql += '        	-- 랭크값을 몇개 심어야됨'+char(10)
  --SET @v_dSql += '        	-- : CELL_GROUP_CODE 별, 그리고 각 ui계산로직별로 그룹값을 가지고 있어야함(EOH(Shipping Plan), EOH(SCP Target), Cell Request, Remained Activated Cell, EOH(Plan), 특성 Request, SCP_Balance)'+char(10)
  SET @v_dSql += '        	, DENSE_RANK() OVER( ORDER BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.CELL_GROUP_CODE ) AS CELL_GROUP_CODE_RANK'+char(10)
  --SET @v_dSql += '        	, DENSE_RANK() OVER( ORDER BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.CELL_GROUP_CODE, A.PACK_GROUP_CODE) AS PACK_RANK -- 팩만 유효(셀,활성화는 참조하면 안됨)'+char(10)
  SET @v_dSql += '        	, DENSE_RANK() OVER( ORDER BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.CELL_GROUP_CODE, A.PACK_GROUP_CODE) AS PACK_RANK '+char(10)
  SET @v_dSql += '        	, (CASE WHEN A.DATA_TYPE = ''DATA'' AND A.CATEGORY_ID IN (''PACK_P_OUT'',''FORM_P_OUT'',''CELL_P_OUT_CELL'') AND B.LINE_ID IS NOT NULL'+char(10)
  --ET @v_dSql += '         	        -- check release verion'+char(10)
  SET @v_dSql += '         	        THEN (CASE WHEN A.CATEGORY_ID = ''PACK_P_OUT'' AND'+char(10)
  SET @v_dSql += '' + @v_is_rel_pack+''+char(10)
  SET @v_dSql += ' != ''Y'' THEN ''Y'''+char(10)
  SET @v_dSql += '							               WHEN A.CATEGORY_ID = ''FORM_P_OUT'' AND'+char(10)
  SET @v_dSql += '' + @v_is_rel_form+''+char(10)
  SET @v_dSql += ' != ''Y'' THEN ''Y'''+char(10)
  SET @v_dSql += '							               WHEN A.CATEGORY_ID = ''CELL_P_OUT_CELL'' AND'+char(10)
  SET @v_dSql += '' + @v_is_rel_assy+''+char(10)
  SET @v_dSql += ' != ''Y'' THEN ''Y'''+char(10)
  SET @v_dSql += '							               ELSE ''N'' END )'+char(10)
  SET @v_dSql += '        	        ELSE ''N'' END) AS EDIT_YN'+char(10)
  SET @v_dSql += '      FROM ('+char(10)
  --SET @v_dSql += '      	-- pack : pack item id -> pack group code, pack item id -> cell item id -> cell group code 순서로 찾는다...'+char(10)
  --SET @v_dSql += '      	-- * Pack : sales'+char(10)
  SET @v_dSql += '      	SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.OPERATION_ID, A.PRODUCTION_TYPE, A.MARKET, A.LINE_ID'+char(10)
  SET @v_dSql += '      		, B.CELL_ITEM_ID, E.NICK_NAME AS CELL_NICK_NAME, B.CELL_ITEM_ID AS CELL_GROUP_CODE'+char(10)
  SET @v_dSql += '      		, ''-'' AS PACK_ITEM_ID, ''-'' AS PACK_NICK_NAME, A.PACK_GROUP_CODE'+char(10)
  SET @v_dSql += '      		, SUM(A.BOH_QTY) AS BOH_QTY, A.ITEM_TYPE, NULL AS BOM_RATE, NULL AS LT'+char(10)
  SET @v_dSql += '      		, A.CATEGORY_ID, A.CATEGORY_NAME, A.CATEGORY_ORDER, A.PSI_ORDER, A.SHOP_TYPE, A.SHOP_ORDER'+char(10)
  SET @v_dSql += '      		, A.DATA_TYPE'+char(10)
  ---- REMAINED SCRIPT (PLEASE CONVERT THIS MANUALLY----
  SET @v_dSql += @BUCKET_SCRIPT_PART10
  --SET @v_dSql += '
