  --'
  SET @v_dSql += '      	FROM MAIN_PACK_S A'+char(10)
  --SET @v_dSql += '      	-- bom 정보를 이용해서 cell item 정보 가져옴'+char(10)
  SET @v_dSql += '      	INNER HASH JOIN ('+char(10)
  SET @v_dSql += '      			SELECT B.COMPANY_ID, B.DIVISION_ID, B.SITE_ID, B.PLANT_ID, B.PARENT_ITEM_ID, MAX(B.CELL_ITEM_ID) AS CELL_ITEM_ID'+char(10)
  SET @v_dSql += '      			FROM   BOM_INFO B WITH(NOLOCK)'+char(10)
  SET @v_dSql += '      			WHERE  B.RNK = 1'+char(10)
  SET @v_dSql += '      			GROUP BY B.COMPANY_ID, B.DIVISION_ID, B.SITE_ID, B.PLANT_ID, B.PARENT_ITEM_ID'+char(10)
  SET @v_dSql += '      	) B'+char(10)
  SET @v_dSql += '      	ON  A.COMPANY_ID   = B.COMPANY_ID'+char(10)
  SET @v_dSql += '      	AND A.DIVISION_ID  = B.DIVISION_ID'+char(10)
  SET @v_dSql += '      	AND A.SITE_ID      = B.SITE_ID'+char(10)
  SET @v_dSql += '      	AND A.PLANT_ID     = B.PLANT_ID'+char(10)
  SET @v_dSql += '      	AND A.PACK_ITEM_ID = B.PARENT_ITEM_ID'+char(10)
  --SET @v_dSql += '      	INNER HASH JOIN SCM_ITEM_M E WITH(NOLOCK) -- cell nick name'+char(10)
  SET @v_dSql += '      	INNER HASH JOIN SCM_ITEM_M E WITH(NOLOCK) '+char(10)
  SET @v_dSql += '      	ON     B.COMPANY_ID     = E.COMPANY_ID'+char(10)
  SET @v_dSql += '      	AND    B.DIVISION_ID    = E.DIVISION_ID'+char(10)
  SET @v_dSql += '      	AND    B.SITE_ID        = E.SITE_ID'+char(10)
  SET @v_dSql += '      	AND    B.CELL_ITEM_ID   = E.ITEM_ID'+char(10)
  SET @v_dSql += '      	WHERE  1=1'+char(10)
  SET @v_dSql += ' ' +@opt_23assy_item_id +' '+''+char(10)--AND    B.CELL_ITEM_ID LIKE '%' + #ASSY_ITEM_ID# + '%'
  SET @v_dSql += ' ' +@opt_11assy_nick_name +' '+''+char(10)--AND    E.NICK_NAME LIKE '%' + #ASSY_NICK_NAME# + '%'
  SET @v_dSql += '      	GROUP BY A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.OPERATION_ID, A.PRODUCTION_TYPE, A.MARKET, A.LINE_ID'+char(10)
  SET @v_dSql += '          		, B.CELL_ITEM_ID, A.PACK_GROUP_CODE, E.NICK_NAME, B.CELL_ITEM_ID, A.ITEM_TYPE'+char(10)
  SET @v_dSql += '          		, A.CATEGORY_ID, A.CATEGORY_NAME, A.CATEGORY_ORDER, A.PSI_ORDER, A.SHOP_TYPE, A.SHOP_ORDER'+char(10)
  SET @v_dSql += '          		, A.DATA_TYPE'+char(10)
  --SET @v_dSql += '      	-- * Pack : Production'+char(10)
