  SET @v_dSql += '      	SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.OPERATION_ID, A.PRODUCTION_TYPE, A.MARKET, A.LINE_ID'+char(10)
  SET @v_dSql += '      		, B.CELL_ITEM_ID, E.NICK_NAME AS CELL_NICK_NAME, B.CELL_ITEM_ID AS CELL_GROUP_CODE'+char(10)
  SET @v_dSql += '      		, A.PACK_ITEM_ID, A.PACK_NICK_NAME, A.PACK_GROUP_CODE'+char(10)
  SET @v_dSql += '      		, A.BOH_QTY, A.ITEM_TYPE, NULL AS BOM_RATE, ISNULL(D.MOVING_TIME_DAY,0) AS LT'+char(10)
  SET @v_dSql += '      		, A.CATEGORY_ID, A.CATEGORY_NAME, A.CATEGORY_ORDER, A.PSI_ORDER, A.SHOP_TYPE, A.SHOP_ORDER'+char(10)
  SET @v_dSql += '      		, A.DATA_TYPE'+char(10)
  ---- REMAINED SCRIPT (PLEASE CONVERT THIS MANUALLY----
  SET @v_dSql += @BUCKET_SCRIPT_PART11
  --SET @v_dSql += '
  --{
  --    				var sql="";
