  --
  --				    if(list.size() > 0) {
  --							for(var i = 0; i < list.size(); i++) {
  --							  sql+="      		, A.D" + i + "\r\n";
  --							}
  --				    }
  --          }

  --'
  SET @v_dSql += '      	FROM MAIN_PACK_P A'+char(10)
  --SET @v_dSql += '      	-- bom 정보를 이용해서 cell item 정보 가져옴'+char(10)
  SET @v_dSql += '      	INNER HASH JOIN ('+char(10)
  SET @v_dSql += '      			SELECT B.COMPANY_ID, B.DIVISION_ID, B.SITE_ID, B.PLANT_ID, B.PARENT_ITEM_ID, MAX(B.CELL_ITEM_ID) AS CELL_ITEM_ID'+char(10)
  SET @v_dSql += '      			FROM   BOM_INFO B WITH(NOLOCK)'+char(10)
  SET @v_dSql += '      			WHERE  B.RNK = 1'+char(10)
  SET @v_dSql += '      			GROUP BY B.COMPANY_ID, B.DIVISION_ID, B.SITE_ID, B.PLANT_ID, B.PARENT_ITEM_ID'+char(10)
  SET @v_dSql += '      	) B'+char(10)
  SET @v_dSql += '      	ON  A.COMPANY_ID   = B.COMPANY_ID'+char(10)
  SET @v_dSql += '      	AND A.DIVISION_ID  = B.DIVISION_ID'+char(10)
  SET @v_dSql += '      	AND A.SITE_ID      = B.SITE_ID'+char(10)
  SET @v_dSql += '      	AND A.PLANT_ID     = B.PLANT_ID'+char(10)
  SET @v_dSql += '      	AND A.PACK_ITEM_ID = B.PARENT_ITEM_ID'+char(10)
  SET @v_dSql += '    		INNER HASH JOIN SCM_LINE_M C WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    		ON     A.COMPANY_ID     = C.COMPANY_ID'+char(10)
  SET @v_dSql += '    		AND    A.DIVISION_ID    = C.DIVISION_ID'+char(10)
  SET @v_dSql += '    		AND    A.SITE_ID        = C.SITE_ID'+char(10)
  SET @v_dSql += '    		AND    A.PLANT_ID       = C.PLANT_ID'+char(10)
  SET @v_dSql += '    		AND    A.FACTORY_ID     = C.FACTORY_ID'+char(10)
  SET @v_dSql += '    		AND    A.OPERATION_ID   = C.OPERATION_ID'+char(10)
  SET @v_dSql += '    		AND    A.LINE_ID        = C.LINE_ID'+char(10)
  SET @v_dSql += '    		LEFT OUTER JOIN ('+char(10)
  --SET @v_dSql += '    				--< 특성 L/T 가져오기 >--'+char(10)
  SET @v_dSql += '    				SELECT A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID, A.OPERATION_ID'+char(10)
  SET @v_dSql += '    					 , A.MODEL_TYPE, A.LINE_ATTR_1'+char(10)
  SET @v_dSql += '    					 , BB.BUFFER_TIME'+char(10)
  SET @v_dSql += '    					 , ISNULL(BB.BUFFER_TIME_UOM,''MINUTE'') AS BUFFER_TIME_UOM'+char(10)
  SET @v_dSql += '    					 , CASE WHEN  ISNULL(BB.BUFFER_TIME_UOM,''MINUTE'') = ''MINUTE''  THEN  CEILING(ISNULL(BB.BUFFER_TIME,0)/1440)'+char(10)
  SET @v_dSql += '    							    WHEN  ISNULL(BB.BUFFER_TIME_UOM,''MINUTE'') = ''HOUR''    THEN  CEILING(ISNULL(BB.BUFFER_TIME,0)/24)'+char(10)
  SET @v_dSql += '    							    WHEN  ISNULL(BB.BUFFER_TIME_UOM,''MINUTE'') = ''DAY''     THEN  CEILING(ISNULL(BB.BUFFER_TIME,0))'+char(10)
  SET @v_dSql += '    						      END MOVING_TIME_DAY'+char(10)
  SET @v_dSql += '    				FROM   SCM_OPERATION_MOVE_2_V A WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    				LEFT OUTER JOIN SCM_OPERATION_MOVE_M BB WITH(NOLOCK)'+char(10)
  SET @v_dSql += '    				ON    A.COMPANY_ID    = BB.COMPANY_ID'+char(10)
  SET @v_dSql += '    				AND   A.DIVISION_ID   = BB.DIVISION_ID'+char(10)
  SET @v_dSql += '    				AND   A.SITE_ID       = BB.SITE_ID'+char(10)
  SET @v_dSql += '    				AND   A.PLANT_ID      = BB.PLANT_ID'+char(10)
  SET @v_dSql += '    				AND   A.FACTORY_ID    = BB.FACTORY_ID'+char(10)
  SET @v_dSql += '    				AND   A.OPERATION_ID  = BB.OPERATION_ID'+char(10)
  SET @v_dSql += '    				AND   A.MODEL_TYPE    = BB.MODEL_TYPE'+char(10)
  SET @v_dSql += '    				AND   A.LINE_ATTR_1   = BB.LINE_ATTR_1'+char(10)
  SET @v_dSql += '    				AND   ISNULL(BB.ACTIVE_FLAG, ''Y'')  = ''Y'''+char(10)
  SET @v_dSql += '    				WHERE A.OPERATION_ID IN ( ''P5500'',''P9500'')'+char(10)
  SET @v_dSql += '    		) D'+char(10)
  SET @v_dSql += '    		ON  1=1'+char(10)
  SET @v_dSql += '    		AND A.COMPANY_ID   = D.COMPANY_ID'+char(10)
  SET @v_dSql += '    		AND A.DIVISION_ID  = D.DIVISION_ID'+char(10)
  SET @v_dSql += '    		AND A.SITE_ID      = D.SITE_ID'+char(10)
  SET @v_dSql += '    		AND A.PLANT_ID     = D.PLANT_ID'+char(10)
  SET @v_dSql += '    		AND A.FACTORY_ID   = D.FACTORY_ID'+char(10)
  SET @v_dSql += '    		AND C.MODEL_TYPE   = D.MODEL_TYPE'+char(10)
  SET @v_dSql += '    		AND C.LINE_ATTR_1  = D.LINE_ATTR_1'+char(10)
  SET @v_dSql += '    		AND A.OPERATION_ID = D.OPERATION_ID'+char(10)
  --SET @v_dSql += '      	INNER HASH JOIN SCM_ITEM_M E WITH(NOLOCK) -- cell nick name'+char(10)
